/// <summary>
/// COC for Picking list registration update form
/// </summary>
[ExtensionOf(formControlStr(WMSPickingRegistration, PickQtyUpdateButton))]
final class METWMSPickingRegistration_PickQtyUpdateCtrl_Extension
{
}

Method.Source:
/// <summary>
/// Handles the click event for the control. Updates the METPickedQtyUpdated flag
/// for activated picking routes, and notifies the user about updated routes.
/// </summary>
void  clicked()
{
    next clicked();

    FormControl             formButtonControl   = any2Object(this) as FormControl;
    FormDataSource          wMSPickingRoute_ds  = formButtonControl.formRun().dataSource(tableStr(WMSPickingRoute));
    WMSPickingRoute         wmsPickingRoute;
    WMSOrderTrans           wMSOrderTrans;
    List                    pickingRouteList = new List(Types::String);   

    MultiSelectionHelper helper = MultiSelectionHelper::construct();

    helper.parmDatasource(wMSPickingRoute_ds);

    wmsPickingRoute = helper.getFirst();
    while (wmsPickingRoute.RecId != 0)
    {
        update_recordset wMSOrderTrans
            setting METPickedQtyUpdated = true
                where wMSOrderTrans.routeId == wmsPickingRoute.pickingRouteID   &&
                    wmsordertrans.METPickedQtyUpdated == false &&
                    wmsordertrans.expeditionStatus == WMSExpeditionStatus::Activated;

        if (wMSOrderTrans.RowCount() > 0)
        {
            pickingRouteList.addEnd(wmsPickingRoute.PickingRouteID);
        }

        wmsPickingRoute = helper.getNext();
    }

    if (pickingRouteList.empty())
    {
        warning("@MET:ValidPickRouteNotAvail");
    }
    else
    {
        Info(strFmt("@MET:ListRouteUpdated", pickingRouteList.toString()));
    }
}
